  ui_story_30040601_47_dialog_content = "...",
  ui_story_30040601_48_dialog_content = "Berhentilah berdiri, Kuma! Anda seharusnya bermain mati! Cepat, PlayerName, berteriak bahwa ada orang mati di sini!",
